mapper.select:
SELECT pay05_relate_appr_id                                                                      AS relate_appr_id,
       pay05_appr_id                                                                             AS appr_id,
       b.apr01_status_cd                                                                         AS status_code,
       f_cdnm('AprStatusCode', b.apr01_status_cd, pay05_company_id, b.apr01_reg_date)            AS status_name
  FROM pay05_relate_appr
       LEFT OUTER JOIN apr01_appr b ON pay05_appr_id = apr01_appr_id
 WHERE pay05_company_id = #{companyId}
   AND pay05_pay_cd     = #{payCode}
   AND pay05_start_date = #{payDate}
